operation.add:
// TicketBAI (modulo TicketBai): autoinstalacion idempotente
try {
	$this->load->model('ticketbai/ticketbai');
	$this->model_ticketbai_ticketbai->install();

	$ticketbai_group = $this->db->query("SELECT permission FROM `" . DB_PREFIX . "user_group` WHERE user_group_id = 1");

	if ($ticketbai_group->num_rows) {
		$ticketbai_perm = unserialize($ticketbai_group->row['permission']);

		if (is_array($ticketbai_perm) && isset($ticketbai_perm['access']) && isset($ticketbai_perm['modify'])) {
			$ticketbai_perm_changed = false;

			foreach (array('access', 'modify') as $ticketbai_type) {
				if (!in_array('ticketbai/ticketbai', $ticketbai_perm[$ticketbai_type])) {
					$ticketbai_perm[$ticketbai_type][] = 'ticketbai/ticketbai';
					$ticketbai_perm_changed = true;
				}
			}

			if ($ticketbai_perm_changed) {
				$this->db->query("UPDATE `" . DB_PREFIX . "user_group` SET permission = '" . $this->db->escape(serialize($ticketbai_perm)) . "' WHERE user_group_id = 1");
			}
		}
	}
} catch (Exception $ticketbai_install_exception) {
	// No interrumpir la carga del admin; se reintenta en la siguiente carga.
}

if ($this->user->hasPermission('access', 'ticketbai/ticketbai')) {
	$sales[] = array(
		'name' => $this->language->get('text_ticketbai'),
		'href' => $this->url->link('ticketbai/ticketbai', 'token=' . $this->session->data['token'], 'SSL'),
		'children' => array()
	);
}

// TicketBAI (modulo TicketBai): firma y envio a la Hacienda Foral. $rectified_invoice_id > 0
// la emite como rectificativa de esa factura.
public function ticketbaiSend($invoice_id, $rectified_invoice_id = 0) {
	$this->load->model('sale/invoice');
	$this->load->model('localisation/country');
	$this->load->model('localisation/zone');
	$this->load->model('ticketbai/ticketbai');

	$tbai_invoice_info = $this->model_sale_invoice->getInvoice($invoice_id);

	if ($tbai_invoice_info) {
		list($tbai_seller, $tbai_buyer) = $this->getFacturaeParties($tbai_invoice_info);
	} else {
		$tbai_seller = array('nif' => '', 'name' => '');
		$tbai_buyer = array('nif' => '', 'name' => '');
	}

	return $this->model_ticketbai_ticketbai->send($invoice_id, $tbai_seller, $tbai_buyer, $rectified_invoice_id);
}

$tbai_label = '';

if ($this->config->get('ticketbai_active') && is_file(DIR_APPLICATION . 'model/ticketbai/ticketbai.php')) {
	$qr_registered = false;

	$this->load->model('ticketbai/ticketbai');

	$tbai_qr = $this->model_ticketbai_ticketbai->getQr($invoice_id);

	if ($tbai_qr) {
		require_once(DIR_SYSTEM . 'external/tcpdf/tcpdf_barcodes_2d.php');

		$tbai_barcode = new TCPDF2DBarcode($tbai_qr['url'], 'QRCODE,M');
		$tbai_png = $tbai_barcode->getBarcodePngData(6, 6, array(0, 0, 0));

		if ($tbai_png !== false) {
			$qr_code = 'data:image/png;base64,' . base64_encode($tbai_png);
			$qr_code_pdf = DIR_CACHE . 'qr_invoice_' . $invoice_id . '.png';
			file_put_contents($qr_code_pdf, $tbai_png);
			$tbai_label = $tbai_qr['identifier'];
		}
	}
}
